    auto *actions=new QHBoxLayout;auto button=[&](const QString &text,const QString &name,std::function<void()> action){auto *value=new QPushButton(text,this);value->setObjectName(name);actions->addWidget(value);connect(value,&QPushButton::clicked,this,std::move(action));};button(tr("Save and sync only"),"PrepareDistributedRelease",[this]{Publish();});button(tr("Start selected group only"),"ActivateDistributedRelease",[this]{Activate();});button(tr("Refresh / check original operation"),"ObserveDistributedRelease",[this]{Observe();});button(tr("Stop selected group"),"StopDistributedGroup",[this]{StopSelected(false);});button(tr("Terminate selected group…"),"TerminateDistributedGroup",[this]{StopSelected(true);});button(tr("Review terminated group…"),"ReviewTerminatedGroup",[this]{ReviewTerminatedGroup();});controls->addLayout(actions);layout->addWidget(fControls,3);auto *waiting=new QHBoxLayout;fWaitStatus=new QLabel(tr("Ready. Add a host and boards, then start the selected services."),this);fWaitStatus->setObjectName("DeploymentWaitStatus");fWaitStatus->setWordWrap(true);fStopWaiting=new QPushButton(tr("Stop waiting"),this);fStopWaiting->setObjectName("StopDeploymentWaiting");fStopWaiting->setEnabled(false);waiting->addWidget(fWaitStatus,1);waiting->addWidget(fStopWaiting);layout->addLayout(waiting);connect(fStopWaiting,&QPushButton::clicked,this,[this]{if(fCanceled)fCanceled->store(true);fStopWaiting->setEnabled(false);fWaitStatus->setText(tr("Stopping local waiting. Accepted backend work is retained; use Refresh to check it."));});auto *waitTimer=new QTimer(this);waitTimer->setInterval(1000);connect(waitTimer,&QTimer::timeout,this,[this]{if(fBusy && fCanceled && !fCanceled->load())fWaitStatus->setText(tr("%1 — %2 s. You can stop waiting without replaying accepted work.").arg(fWaitStage).arg(fWaitClock.elapsed()/1000));});waitTimer->start();fLog=new QPlainTextEdit(this);fLog->setObjectName("DistributedDeploymentLog");fLog->setReadOnly(true);fLog->setMaximumBlockCount(500);layout->addWidget(fLog,1);auto *footer=new QHBoxLayout;footer->addStretch();auto *use=new QPushButton(tr("Use this ECC in Run Setup"));use->setObjectName("UseDistributedGroup");auto *close=new QPushButton(tr("Close (keep services running)"));footer->addWidget(use);footer->addWidget(close);layout->addLayout(footer);connect(use,&QPushButton::clicked,this,&DistributedDeploymentWindow::UseSelected);connect(close,&QPushButton::clicked,this,&DistributedDeploymentWindow::reject);connect(fDailyGroups,QOverload<int>::of(&QComboBox::currentIndexChanged),this,[this](int index){if(index<0)return;const auto id=fDailyGroups->itemData(index).toString();for(int row=0;row<fGroups->rowCount();++row)if(fGroups->item(row,0)->data(Qt::UserRole).toString()==id)fGroups->setCurrentCell(row,0);});connect(fGroups,&QTableWidget::itemSelectionChanged,this,[this]{const QSignalBlocker blocker(fDailyGroups);fDailyGroups->setCurrentIndex(fDailyGroups->findData(SelectedGroup()));});connect(fAdvanced,&QCheckBox::toggled,this,[this,tabs](bool show){tabs->setVisible(show);for(const auto &name:{"PrepareDistributedRelease","ActivateDistributedRelease","TerminateDistributedGroup"})if(auto *button=findChild<QPushButton *>(name))button->setVisible(show);});
