void DistributedDeploymentWindow::RequestClose(){if(!fBusy){QDialog::reject();return;}fCloseAfterWait=true;if(fCanceled)fCanceled->store(true);fWaitStatus->setText(tr("Stopping local waiting before closing. Backend work and audit records are retained."));fStopWaiting->setEnabled(false);}
void DistributedDeploymentWindow::reject(){RequestClose();}
Logger DistributedDeploymentWindow::Logger(){const QPointer<DistributedDeploymentWindow> guard(this);return [guard](const QString &text){if(guard)QMetaObject::invokeMethod(guard,[guard,text]{if(guard){guard->fLog->appendPlainText(text);guard->fWaitStage=text.left(240);}},Qt::QueuedConnection);};}
void DistributedDeploymentWindow::Async(std::function<QJsonObject()> task,std::function<void(QJsonObject)> done){
    if(fBusy)return;
    fBusy=true;fCloseAfterWait=false;fCanceled=std::make_shared<std::atomic_bool>(false);fWaitClock.start();fWaitStage=tr("Checking services at %1:%2").arg(fAddress->text()).arg(fPort->value());fWaitStatus->setText(fWaitStage);fStopWaiting->setEnabled(true);fControls->setEnabled(false);
    const auto canceled=fCanceled;auto *watcher=new QFutureWatcher<QPair<QJsonObject,QString>>(this);
    connect(watcher,&QFutureWatcher<QPair<QJsonObject,QString>>::finished,this,[this,watcher,done]{const auto result=watcher->result();watcher->deleteLater();fBusy=false;fStopWaiting->setEnabled(false);fControls->setEnabled(true);if(!result.second.isEmpty()){fLog->appendPlainText(tr("Operation incomplete: %1").arg(result.second));fWaitStatus->setText(result.second);}else{try{done(result.first);fWaitStatus->setText(tr("Operation finished. Check the result below."));}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));fWaitStatus->setText(QString::fromUtf8(error.what()));}}if(fCloseAfterWait)QDialog::reject();});
    watcher->setFuture(QtConcurrent::run([task,canceled]{OperationScope scope(canceled);try{return qMakePair(task(),QString());}catch(const std::exception &error){return qMakePair(QJsonObject(),QString::fromUtf8(error.what()));}}));
}

void DistributedDeploymentWindow::OpenProject(const QString &directory){if(fBusy)return;try{auto project=Parse(Read(directory+"/project.json",64*1024*1024));auto pairedNodes=project["nodes"].toArray();for(const auto &name:QDir(directory+"/paired-nodes").entryList({"*.json"},QDir::Files)){const auto node=Parse(Read(directory+"/paired-nodes/"+name));bool present=false;for(const auto &entry:pairedNodes)present=present || entry.toObject()["id"]==node["id"];if(!present)pairedNodes.append(node);}project["nodes"]=pairedNodes;Require(project["schema"].toInt()==1 && project["kind"]=="getdaq.distributed-project","Unsupported project file");QMap<QString,QByteArray> loaded;for(const auto &value:project["content_files"].toArray()){const auto entry=value.toObject();const auto sha=Digest(entry["sha256"].toString());const auto bytes=entry.contains("base64")?QByteArray::fromBase64(entry["base64"].toString().toLatin1()):Read(directory+"/content/"+sha,16*1024*1024);Require(Sha(bytes)==sha,"Saved project source differs");loaded[Id(entry["id"].toString())]=bytes;}for(const auto &value:project["nodes"].toArray()){const auto node=value.toObject();Require(node["credential_file"].toString()==directory+"/nodes/"+Id(node["id"].toString())+".token","Imported node credential must belong to this private project directory");}fFiles=loaded;fProject=project;fRoot->setText(directory);fMaster=QJsonObject();if(QFile::exists(directory+"/master.json")){fMaster=Parse(Read(directory+"/master.json"));fAddress->setText(fMaster["address"].toString());fPort->setValue(fMaster["port"].toInt());}fPreparation=QFile::exists(directory+"/prepared-release.json")?Parse(Read(directory+"/prepared-release.json",64*1024*1024)):QJsonObject();fActivation=QFile::exists(directory+"/active-release.json")?Parse(Read(directory+"/active-release.json",64*1024*1024)):QJsonObject();QSettings().setValue(StartupConfigurationKey()+"/distributed-project",directory);RefreshTables();const auto pending=QDir(directory+"/pending-pairings").entryList({"*.json"},QDir::Files);if(!pending.isEmpty()){fInvitation->setText("getdaq-pair:"+QString::fromLatin1(Read(directory+"/pending-pairings/"+pending[0]).toBase64(QByteArray::Base64UrlEncoding|QByteArray::OmitTrailingEquals)));fLog->appendPlainText(tr("An earlier pairing is unresolved. Its original code has been restored; use Add slave to recover its result."));}fLog->appendPlainText(tr("Project loaded. Saved records do not prove remote services are online; refresh to check."));}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}
void DistributedDeploymentWindow::SaveProject(){PrivateDirectory(fRoot->text());auto nodes=fProject["nodes"].toArray();for(int row=0;row<fHosts->rowCount() && row<nodes.size();++row){auto node=nodes[row].toObject();if(auto *item=fHosts->item(row,0))node["name"]=item->text();nodes[row]=node;}fProject["nodes"]=nodes;QJsonArray entries;for(auto it=fFiles.begin();it!=fFiles.end();++it){const auto sha=Sha(it.value());Write(fRoot->text()+"/content/"+sha,it.value(),true);entries.append(QJsonObject{{"id",it.key()},{"sha256",sha},{"bytes",it.value().size()}});}fProject["content_files"]=entries;Write(fRoot->text()+"/project.json",Json(fProject));QSettings().setValue(StartupConfigurationKey()+"/distributed-project",fRoot->text());}
void DistributedDeploymentWindow::RefreshTables(){const auto previousGroup=SelectedGroup();const QSignalBlocker blocker(fDailyGroups);fDailyGroups->clear();const auto nodes=fProject["nodes"].toArray();fHosts->setRowCount(nodes.size());for(int row=0;row<nodes.size();++row){const auto node=nodes[row].toObject(),inventory=node["inventory"].toObject();const QStringList values={node["name"].toString(),node["url"].toString(),node["id"].toString(),inventory["data_directory"].toString(),node["observation"].toString(tr("Paired, not observed"))};for(int column=0;column<values.size();++column){auto *item=new QTableWidgetItem(values[column]);if(column)item->setFlags(item->flags()&~Qt::ItemIsEditable);fHosts->setItem(row,column,item);}}const auto groups=fProject["groups"].toArray();fGroups->setRowCount(groups.size());for(int row=0;row<groups.size();++row){const auto group=groups[row].toObject(),ecc=group["ecc"].toObject();fDailyGroups->addItem(group["name"].toString(group["id"].toString()),group["id"].toString());QStringList dataHosts;for(const auto &value:group["receivers"].toArray()){const auto receiver=value.toObject();try{dataHosts<<NodeById(nodes,receiver["node_id"].toString())["name"].toString();}catch(...){dataHosts<<receiver["node_id"].toString();}}QString eccHost=ecc["node_id"].toString();try{eccHost=NodeById(nodes,eccHost)["name"].toString();}catch(...){}QString state=tr("Configuration draft");if(fPreparation["phase"]=="prepared")state=tr("Prepared; check runtime version");if(fActivation["phase"]=="active" && fActivation["release_id"]==fPreparation["release_id"])state=tr("Previously activated; refresh to check");for(const auto &nodeValue:nodes)for(const auto &instanceValue:nodeValue.toObject()["inventory"].toObject()["instances"].toArray()){const auto instance=instanceValue.toObject();if(instance["group_id"]==group["id"] && instance["role"]=="ecc" && instance.contains("actual_state"))state=tr("Last observed: %1 (runtime release %2)").arg(instance["actual_state"].toString(),instance["release_id"].toString().left(12));}const QStringList values={group["name"].toString(group["id"].toString()),eccHost+':'+QString::number(ecc["port"].toInt()),dataHosts.join(", "),QString::number(group["senders"].toArray().size()),state};for(int column=0;column<values.size();++column){auto *item=new QTableWidgetItem(values[column]);item->setFlags(item->flags()&~Qt::ItemIsEditable);item->setData(Qt::UserRole,group["id"].toString());fGroups->setItem(row,column,item);}}int selected=fDailyGroups->findData(previousGroup);if(selected<0 && fDailyGroups->count())selected=0;fDailyGroups->setCurrentIndex(selected);if(selected>=0)fGroups->setCurrentCell(selected,0);}
void DistributedDeploymentWindow::StartMaster(){try{SaveProject();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));return;}const auto root=fRoot->text(),programs=QCoreApplication::applicationDirPath(),address=fAddress->text();const int port=fPort->value();Async([=]{return EnsureMaster(root,programs,address,port);},[this](QJsonObject result){fMaster=result;fRoot->setReadOnly(true);fAddress->setReadOnly(true);fPort->setEnabled(false);SaveProject();fLog->appendPlainText(tr("Master HTTPS configuration service ready. Add an execution host or use this computer."));});}
void DistributedDeploymentWindow::PairHost(){try{SaveProject();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));return;}const auto invitation=fInvitation->text();if(invitation.trimmed().isEmpty()){fLog->appendPlainText(tr("Enable the slave and copy its one-time pairing code first."));return;}const auto root=fRoot->text(),programs=QCoreApplication::applicationDirPath(),address=fAddress->text();const int port=fPort->value();const auto log=Logger();Async([=]{log("Starting / checking master configuration service…");const auto master=EnsureMaster(root,programs,address,port);log("Connecting to the slave and checking its pairing identity…");return QJsonObject{{"master",master},{"node",PairNode(master,invitation)}};},[this](QJsonObject result){fMaster=result["master"].toObject();auto nodes=fProject["nodes"].toArray();const auto node=result["node"].toObject();for(const auto &value:nodes)Require(value.toObject()["id"]!=node["id"],"This node is already in the project");nodes.append(node);fProject["nodes"]=nodes;fInvitation->clear();SaveProject();RefreshTables();fLog->appendPlainText(tr("Host paired and identity verified. You can now add an ECC / board group."));});}
void DistributedDeploymentWindow::LocalNode(){try{SaveProject();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));return;}
    const auto root=fRoot->text(),programs=QCoreApplication::applicationDirPath(),address=fAddress->text();const int port=fPort->value();const auto log=Logger();
    Async([=]{log("Starting / checking master configuration service…");const auto master=EnsureMaster(root,programs,address,port);log("Starting / checking the local node agent…");const auto localRoot=QSettings().value(StartupConfigurationKey()+"/slave-cache-directory",QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation)+"/local-node").toString();QJsonObject settings{{"bind",address},{"port",24260},{"data_directory",QStandardPaths::writableLocation(QStandardPaths::AppLocalDataLocation)+"/data"}};if(QFile::exists(localRoot+"/node.json"))settings=Parse(Read(localRoot+"/node.json"));auto node=EnsureLocalNode(localRoot,programs,settings["bind"].toString(),settings["port"].toInt(),settings["data_directory"].toString());if(!node["paired"].toBool())node=PairNode(master,node["invitation"].toString());else {const auto paired=Parse(Read(localRoot+"/master.json"));Require(paired["repository_id"]==master["repository_id"] && paired["repository_url"]==master["repository_url"],"This computer is already joined to another master project; open that project first");const auto credential=root+"/nodes/"+Id(node["id"].toString())+".token";Write(credential,Secret(node["credential_file"].toString())+'\n');node["credential_file"]=credential;node.remove("invitation");}node["name"]=tr("This computer");return QJsonObject{{"master",master},{"node",node}};},[this](QJsonObject result){fMaster=result["master"].toObject();auto nodes=fProject["nodes"].toArray();const auto node=result["node"].toObject();bool found=false;for(int i=0;i<nodes.size();++i)if(nodes[i].toObject()["id"]==node["id"]){nodes[i]=node;found=true;}if(!found)nodes.append(node);fProject["nodes"]=nodes;SaveProject();RefreshTables();fLog->appendPlainText(tr("This computer joined automatically. Add boards, then click Start services and use this configuration."));});
}
void DistributedDeploymentWindow::EditGroup(bool existing){if(fBusy)return;const auto nodes=fProject["nodes"].toArray();if(nodes.isEmpty()){fLog->appendPlainText(tr("Add at least one execution host first, or click Use this computer (automatic)."));return;}QString id;QJsonObject previous;if(existing){id=SelectedGroup();for(const auto &value:fProject["groups"].toArray())if(value.toObject()["id"]==id)previous=value.toObject();if(previous.isEmpty())return;}else id="g-"+QString::fromLatin1(Token().left(12));QDialog selection(this);selection.setWindowTitle(tr("ECC and receiver hosts"));QFormLayout form(&selection);QLineEdit name(previous["name"].toString(tr("ECC-%1").arg(fProject["groups"].toArray().size()+1)));QComboBox ecc,data;for(const auto &value:nodes){const auto node=value.toObject();ecc.addItem(node["name"].toString()+" · "+QUrl(node["url"].toString()).host(),node["id"].toString());data.addItem(ecc.itemText(ecc.count()-1),node["id"].toString());}if(existing){ecc.setCurrentIndex(ecc.findData(previous["ecc"].toObject()["node_id"].toString()));if(!previous["receivers"].toArray().isEmpty())data.setCurrentIndex(data.findData(previous["receivers"].toArray()[0].toObject()["node_id"].toString()));}form.addRow(tr("Instance name"),&name);form.addRow(tr("ECC host"),&ecc);form.addRow(tr("Data receiver host"),&data);QDialogButtonBox buttons(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);form.addRow(&buttons);connect(&buttons,&QDialogButtonBox::accepted,&selection,&QDialog::accept);connect(&buttons,&QDialogButtonBox::rejected,&selection,&QDialog::reject);if(nodes.size()>1 && selection.exec()!=QDialog::Accepted)return;try{const auto eccNode=NodeById(nodes,ecc.currentData().toString()),dataNode=NodeById(nodes,data.currentData().toString());HardwareSetupWindow setup(fBase,this);setup.EnableProjectDraftMode();setup.SetReceivingHosts(nodes,dataNode["id"].toString());if(existing && QFile::exists(fRoot->text()+"/drafts/"+id+"/setup-inputs.json"))setup.SetProjectDraft(ReadHardwareDeploymentSetup(fRoot->text()+"/drafts/"+id));auto draft=setup.DraftSetup();const bool moved=!existing || previous["ecc"].toObject()["node_id"]!=eccNode["id"];if(moved)draft.callbackAddress=NodeAddress(eccNode,qEnvironmentVariable("GETDAQ_CONTROL_IPV4","192.168.40.10"));const bool dataMoved=!existing || previous["receivers"].toArray()[0].toObject()["node_id"]!=dataNode["id"];if(dataMoved)for(auto &board:draft.boards)if(board.receivesData){board.receiverNodeId=dataNode["id"].toString();board.receiverAddress=NodeAddress(dataNode,qEnvironmentVariable("GETDAQ_RECEIVER_IPV4","192.168.50.10"));}draft.dataDirectory=dataNode["inventory"].toObject()["data_directory"].toString();if(!existing)draft=SuggestGroupPorts(draft,eccNode["id"].toString(),dataNode["id"].toString(),fProject["groups"].toArray(),nodes);setup.SetProjectDraft(draft);
        while(setup.exec()==QDialog::Accepted){try{draft=setup.DraftSetup();QMap<QString,QJsonArray> assignments;for(const auto &board:draft.boards)if(board.receivesData)assignments[board.receiverNodeId.isEmpty()?dataNode["id"].toString():board.receiverNodeId].append(board.id);QJsonArray placements;int receivingIndex=0;for(auto it=assignments.begin();it!=assignments.end();++it){const auto host=NodeById(nodes,it.key());placements.append(QJsonObject{{"id","data-"+it.key().left(8)},{"node_id",it.key()},{"address",QUrl(host["url"].toString()).host()},{"port",Port(draft.supervisorPort+receivingIndex++)},{"sender_ids",it.value()}});}auto files=fFiles;auto group=CompileGroup(draft,id,eccNode["id"].toString(),QUrl(eccNode["url"].toString()).host(),placements,&files,fFiles);group["name"]=name.text().trimmed();QJsonArray groups;for(const auto &value:fProject["groups"].toArray())if(value.toObject()["id"]!=id)groups.append(value);groups.append(group);QJsonArray hosts;for(const auto &value:nodes)hosts.append(QJsonObject{{"id",value.toObject()["id"]}});BuildBundle(fProject["project_id"].toString(),hosts,groups,files);const auto workspace=fRoot->text()+"/workspaces/"+group["artifact_sha256"].toString();PrivateDirectory(workspace);for(auto it=files.begin();it!=files.end();++it)if(it.key().startsWith(id+'-'))Write(workspace+'/'+it.key(),it.value(),true);draft.experimentFile=workspace+'/'+group["artifact_file"].toString();draft.profileFile=workspace+'/'+group["profile_file"].toString();for(int i=0;i<draft.boards.size();++i){draft.boards[i].templateId=draft.boards[i].id;draft.boards[i].descriptionFile=workspace+'/'+group["descriptions"].toArray()[i].toString();}Write(fRoot->text()+"/drafts/"+id+"/setup-inputs.json",Json(DraftJson(draft)));fProject["groups"]=groups;fFiles=files;SaveProject();RefreshTables();for(int row=0;row<fGroups->rowCount();++row)if(fGroups->item(row,0)->data(Qt::UserRole).toString()==id)fGroups->setCurrentCell(row,0);fLog->appendPlainText(tr("Board group added to the project draft. Remote services have not been changed."));break;}catch(const std::exception &error){QMessageBox::warning(&setup,tr("Check configuration"),QString::fromUtf8(error.what()));}}}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}
QString DistributedDeploymentWindow::SelectedGroup()const{const int row=fGroups->currentRow();return row>=0 && fGroups->item(row,0)?fGroups->item(row,0)->data(Qt::UserRole).toString():(fDailyGroups?fDailyGroups->currentData().toString():QString());}
void DistributedDeploymentWindow::RemoveGroup(){const auto id=SelectedGroup();if(id.isEmpty())return;try{const auto activePath=fRoot->text()+"/active-instances.json";if(QFile::exists(activePath)){const auto active=Parse(Read(activePath));for(auto it=active.begin();it!=active.end();++it)if(it.value().toObject()["group_id"]==id)Require(DeploymentInstanceReleased(it.value().toObject()),"Normally stop this group, or use Review terminated group after inspecting hardware and data");}QJsonArray groups;for(const auto &value:fProject["groups"].toArray())if(value.toObject()["id"]!=id)groups.append(value);fProject["groups"]=groups;SaveProject();RefreshTables();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}
void DistributedDeploymentWindow::Publish(){try{SaveProject();QJsonArray hosts;for(const auto &value:fProject["nodes"].toArray())hosts.append(QJsonObject{{"id",value.toObject()["id"]}});const auto bundle=BuildBundle(fProject["project_id"].toString(),hosts,fProject["groups"].toArray(),fFiles);const auto nodes=fProject["nodes"].toArray();const auto root=fRoot->text(),address=fAddress->text(),programs=QCoreApplication::applicationDirPath();const int port=fPort->value();const auto log=Logger();Async([=]{const auto master=EnsureMaster(root,programs,address,port);return QJsonObject{{"master",master},{"preparation",PrepareProject(master,nodes,bundle,log)}};},[this](QJsonObject result){fMaster=result["master"].toObject();fPreparation=result["preparation"].toObject();RefreshTables();fLog->appendPlainText(tr("All required nodes prepared release %1. You can now start the services." ).arg(fPreparation["release_id"].toString().left(12)));});}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}
void DistributedDeploymentWindow::Activate(){if(fPreparation.isEmpty()){fLog->appendPlainText(tr("Save and sync first, then wait for all required nodes to finish preparing."));return;}const auto master=fMaster,prepared=fPreparation;const auto nodes=fProject["nodes"].toArray();const auto log=Logger();const auto group=SelectedGroup();if(group.isEmpty()){fLog->appendPlainText(tr("Select the ECC group to start first."));return;}Async([=]{return ActivateProject(master,nodes,prepared,log,group);},[this](QJsonObject result){fActivation=result;RefreshTables();fLog->appendPlainText(tr("Service identities verified. Select an ECC group and click Use this ECC in Run Setup, then connect and acquire as usual."));});}
void DistributedDeploymentWindow::Observe(){if(fMaster.isEmpty())return;const auto master=fMaster;const auto nodes=fProject["nodes"].toArray();Async([=]{return ObserveDeployment(master,nodes);},[this](QJsonObject result){auto nodes=fProject["nodes"].toArray();for(const auto &value:result["hosts"].toArray()){const auto observed=value.toObject();for(int i=0;i<nodes.size();++i)if(nodes[i].toObject()["id"]==observed["node_id"]){auto node=nodes[i].toObject();node["observation"]=observed["online"].toBool()?tr("Agent online; see log for instance processes"):tr("Offline: %1").arg(observed["message"].toString());if(observed["online"].toBool())node["inventory"]=observed;nodes[i]=node;}for(const auto &instance:observed["instances"].toArray()){const auto item=instance.toObject();fLog->appendPlainText(QString("%1 / %2: %3, PIDs=%4").arg(observed["name"].toString(),item["instance_id"].toString(),item["actual_state"].toString(item["phase"].toString()),QString::fromUtf8(QJsonDocument(item["actual_pids"].toArray()).toJson(QJsonDocument::Compact))));}}fProject["nodes"]=nodes;for(const auto &value:result["operations"].toArray()){const auto record=value.toObject();fLog->appendPlainText(tr("Original operation %1: %2 %3").arg(record["request"].toObject()["operation_id"].toString(),record["phase"].toString(),record["observation_error"].toString()));}SaveProject();RefreshTables();});}
void DistributedDeploymentWindow::StopSelected(bool repair){const auto group=SelectedGroup();if(group.isEmpty() || fPreparation.isEmpty()){fLog->appendPlainText(tr("Select a deployed ECC group first."));return;}if(repair && QMessageBox::warning(this,tr("Terminate group"),tr("Terminate only matching backend processes in the selected group? This does not prove boards have stopped, complete a Run or clear UNKNOWN."),QMessageBox::Yes|QMessageBox::No,QMessageBox::No)!=QMessageBox::Yes)return;const auto master=fMaster,prepared=fPreparation;const auto nodes=fProject["nodes"].toArray();const auto log=Logger();Async([=]{return StopGroup(master,nodes,prepared,group,repair,log);},[this](QJsonObject result){fLog->appendPlainText(tr("Selected group result: %1").arg(result["phase"].toString()));});}
void DistributedDeploymentWindow::ReviewTerminatedGroup(){
    const auto group=SelectedGroup();if(fBusy || group.isEmpty() || fMaster.isEmpty())return;
    if(QMessageBox::warning(this,tr("Review terminated group"),tr("Continue only after you have verified that board acquisition is stopped (or the boards have been reset) and existing raw data has been preserved.\n\nThe node will verify that matching backend and receiver processes are absent. This releases only the deployment lock so this group can be edited or removed. It does not mark the old Run complete, clear hardware UNKNOWN, delete data, or start hardware.\n\nHave you verified these conditions?"),QMessageBox::Yes|QMessageBox::Cancel,QMessageBox::Cancel)!=QMessageBox::Yes)return;
    const auto master=fMaster;const auto nodes=fProject["nodes"].toArray();const auto log=Logger();
    Async([=]{return ReleaseTerminatedGroup(master,nodes,group,log);},[this](QJsonObject){RefreshTables();fLog->appendPlainText(tr("Inspection release recorded. You can remove this draft group, or save edits and click Start services and use this configuration. Old audit and raw data are retained."));});
}
void DistributedDeploymentWindow::UseSelected(){if(fBusy)return;try{fSelected=ConsoleConfiguration(fMaster,fPreparation,fActivation,SelectedGroup(),fBase);accept();}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}}

void DistributedDeploymentWindow::StartAndUse(){
    try{SaveProject();const auto selected=SelectedGroup();Require(!selected.isEmpty(),"For first-time setup, add an execution host and an ECC / board group.");QJsonArray hosts;for(const auto &value:fProject["nodes"].toArray())hosts.append(QJsonObject{{"id",value.toObject()["id"]}});const auto bundle=BuildBundle(fProject["project_id"].toString(),hosts,fProject["groups"].toArray(),fFiles);const auto nodes=fProject["nodes"].toArray();const auto root=fRoot->text(),address=fAddress->text(),programs=QCoreApplication::applicationDirPath();const int port=fPort->value();const auto log=Logger();Async([=]{log("Starting / checking master configuration service…");const auto master=EnsureMaster(root,programs,address,port);const auto prepared=PrepareProject(master,nodes,bundle,log,selected);const auto active=ActivateProject(master,nodes,prepared,log,selected);return QJsonObject{{"master",master},{"preparation",prepared},{"activation",active}};},[this,selected](QJsonObject result){fMaster=result["master"].toObject();fPreparation=result["preparation"].toObject();fActivation=result["activation"].toObject();if(fCloseAfterWait || (fCanceled && fCanceled->load())){RefreshTables();return;}fSelected=ConsoleConfiguration(fMaster,fPreparation,fActivation,selected,fBase);accept();});}catch(const std::exception &error){fLog->appendPlainText(QString::fromUtf8(error.what()));}
}
